def svg(key: str, css_class: str = "icon") -> str:
    """Render an inline SVG. Falls back to 'building' if key is unknown."""
    body = ICON_LIB.get(key) or ICON_LIB["building"]
    return (
        f'<svg class="{css_class}" viewBox="0 0 24 24" fill="none" '
        f'stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'
        f'{body}</svg>'
    )
